package com.englishhero.vocabulary.phrase;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.englishhero.identity.*;
import com.englishhero.reading.*;
import com.englishhero.reading.translation.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.vocabulary.phrase.PhraseDtos.*;
@Service
@Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
public class PhraseService {
 private final PhraseMapper db;private final IdentityService identities;private final ReadingMapper reading;private final ReadingService visible;private final PracticeSelectionSource practice;private final Clock clock;
 public PhraseService(PhraseMapper db,IdentityService identities,ReadingMapper reading,ReadingService visible,PracticeSelectionSource practice,Clock clock){this.clock=clock;this.practice=practice;this.db=db;this.identities=identities;this.reading=reading;this.visible=visible;}
 static BusinessException conflict(){return new BusinessException(409,"PHRASE_CONFLICT","词组轮次已变化，请重新加载后继续");}
 private long user(SessionPrincipal a,boolean lock){identities.current(a);if(lock)db.lock(a.userId());return a.userId();}
 private Phrase owned(long u,String raw){var p=db.phrase(u,ArticleRules.id(raw,"phraseId"));if(p==null)throw new BusinessException(404,"PHRASE_NOT_FOUND","词组记录不存在");return p;}
 @Transactional(readOnly=true) public Overview list(SessionPrincipal a,String query,boolean cancelled,int page,int pageSize){long u=user(a,false);ArticleRules.page(page);ArticleRules.pageSize(pageSize);String q=query==null?"":query.strip();if(q.length()>160)throw BusinessException.invalid("query","搜索内容过长");var ids=db.jdbc().queryForList("SELECT id FROM vocabulary_phrase WHERE user_id=? AND (?=TRUE OR active=TRUE) AND (display_text LIKE ? OR meaning_zh LIKE ?) ORDER BY updated_at DESC,id DESC LIMIT ? OFFSET ?",Long.class,u,cancelled,"%"+q+"%","%"+q+"%",pageSize,(page-1)*pageSize);var stats=db.jdbc().query("SELECT COALESCE(SUM(active),0),COALESCE(SUM(enrolled AND NOT exempt),0),COALESCE(SUM(independent_passes),0),COALESCE(SUM(enrolled AND NOT exempt AND (stage=0 OR due_at<=?)),0) FROM vocabulary_phrase WHERE user_id=?",(r,n)->new Stats(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4)),Timestamp.from(clock.instant()),u).getFirst();long total=db.jdbc().queryForObject("SELECT COUNT(*) FROM vocabulary_phrase WHERE user_id=? AND (?=TRUE OR active=TRUE) AND (display_text LIKE ? OR meaning_zh LIKE ?)",Long.class,u,cancelled,"%"+q+"%","%"+q+"%");return new Overview(ids.stream().map(id->db.phrase(u,id)).toList(),stats,page,pageSize,total);}
 public Phrase collect(SessionPrincipal a,Collect in){long u=user(a,true);if(in==null)throw BusinessException.invalid("text","请填写词组");String canonical=PhraseRules.canonical(in.text()),meaning=PhraseRules.meaning(in.meaningZh()),note=PhraseRules.note(in.note());Source source=null;
  if(in.source()!=null){var s=in.source();long vid=ArticleRules.id(s.articleVersionId(),"articleVersionId");ReadingDtos.ArticleVersionDto version;
   if(s.practiceAttemptId()!=null||s.paperAttemptId()!=null||s.slot()!=null){version=practice.resolve(a,new SelectionTranslationDtos.Input(null,s.articleId(),s.articleVersionId(),in.text(),"TRANSLATION",s.practiceAttemptId(),s.paperAttemptId(),s.slot()));}
   else {var progress=reading.progress(u,vid);if(progress==null)throw new BusinessException(404,"READING_NOT_FOUND","请先开始阅读此文章");version=visible.version(a,progress.articleId(),s.articleVersionId()).version();}
   var sentence=version.content().paragraphs().stream().flatMap(p->p.sentences().stream()).filter(v->v.key().equals(s.sentenceKey())).findFirst().orElseThrow(()->BusinessException.invalid("sentenceKey","选区已失效"));if(s.startOffset()==null||s.endOffset()==null||s.startOffset()<0||s.endOffset()<=s.startOffset()||s.endOffset()>sentence.text().length()||!canonical.equals(PhraseRules.canonical(sentence.text().substring(s.startOffset(),s.endOffset()))))throw BusinessException.invalid("source","词组与原文选区不一致");if((s.startOffset()>0&&Character.isLetter(sentence.text().charAt(s.startOffset()-1)))||(s.endOffset()<sentence.text().length()&&Character.isLetter(sentence.text().charAt(s.endOffset()))))throw BusinessException.invalid("source","请选择完整词组");source=new Source(null,version.articleId(),s.articleVersionId(),version.title(),s.sentenceKey(),s.startOffset(),s.endOffset(),sentence.text(),s.practiceAttemptId(),s.paperAttemptId(),s.slot());}
  db.jdbc().update("INSERT INTO vocabulary_phrase(user_id,canonical_text,display_text,meaning_zh,note) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE active=TRUE,updated_at=UTC_TIMESTAMP(6)",u,canonical,in.text().strip().replaceAll("\\s+"," "),meaning,note);long id=db.jdbc().queryForObject("SELECT id FROM vocabulary_phrase WHERE user_id=? AND canonical_text=?",Long.class,u,canonical);
  if(source!=null)db.jdbc().update("INSERT INTO vocabulary_phrase_source(phrase_id,article_id,article_version_id,title_snapshot,sentence_key,start_offset,end_offset,sentence_snapshot,practice_attempt_id,paper_attempt_id,paper_slot) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",id,source.articleId(),source.articleVersionId(),source.title(),source.sentenceKey(),source.startOffset(),source.endOffset(),source.sentence(),source.practiceAttemptId(),source.paperAttemptId(),source.slot());return db.phrase(u,id);
 }
 public Phrase edit(SessionPrincipal a,String id,Edit in){long u=user(a,true);owned(u,id);if(in==null)throw BusinessException.invalid("meaningZh","请填写释义");db.jdbc().update("UPDATE vocabulary_phrase SET meaning_zh=?,note=?,updated_at=UTC_TIMESTAMP(6) WHERE user_id=? AND id=?",PhraseRules.meaning(in.meaningZh()),PhraseRules.note(in.note()),u,id);return owned(u,id);}
 public Phrase active(SessionPrincipal a,String id,boolean active){long u=user(a,true);owned(u,id);db.jdbc().update("UPDATE vocabulary_phrase SET active=?,updated_at=UTC_TIMESTAMP(6) WHERE user_id=? AND id=?",active,u,id);return owned(u,id);}
 public Phrase learning(SessionPrincipal a,String id,Learning in){long u=user(a,true);var p=owned(u,id);if(in==null||(in.enrolled()==null&&in.exempt()==null))throw BusinessException.invalid("learning","请选择学习状态");db.jdbc().update("UPDATE vocabulary_phrase SET enrolled=?,exempt=?,updated_at=UTC_TIMESTAMP(6) WHERE user_id=? AND id=?",in.enrolled()==null?p.enrolled():in.enrolled(),in.exempt()==null?p.exempt():in.exempt(),u,id);return owned(u,id);}
 @Transactional(readOnly=true) public Round current(SessionPrincipal a){return db.current(user(a,false));}
 private String request(String r){if(r==null||!r.matches("[A-Za-z0-9_-]{8,80}"))throw BusinessException.invalid("requestId","操作编号无效");return r;}
 private String hash(String route,Object in){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((route+db.encode(in)).getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public Round start(SessionPrincipal a,Start in){long u=user(a,true);if(in==null)throw BusinessException.invalid("mode","请选择练习方式");String req=request(in.requestId()),hash=hash("start",in);var replay=db.replay(u,req,hash);if(replay!=null)return replay;if(db.current(u)!=null)throw conflict();if(!Set.of("RECOGNIZE","WRITE").contains(Objects.toString(in.mode(),"")))throw BusinessException.invalid("mode","请选择看词组或默写");int limit=in.limit()==null?10:in.limit();if(limit<1||limit>50)throw BusinessException.invalid("limit","每轮1至50个词组");var items=db.jdbc().queryForList("SELECT id FROM vocabulary_phrase WHERE user_id=? AND enrolled=TRUE AND exempt=FALSE AND (stage=0 OR due_at<=?) ORDER BY (stage>0) DESC,due_at,id LIMIT ?",Long.class,u,Timestamp.from(clock.instant()),limit).stream().map(id->{var p=db.phrase(u,id);return new Item(p.id(),p.text(),p.meaningZh(),false,0,false,false,"",false,p.ruleVersion());}).toList();if(items.isEmpty())throw BusinessException.invalid("phrases","暂无到期或未学习的词组，请先加入词组或到期后再练习");db.jdbc().update("INSERT INTO vocabulary_phrase_round(user_id,status,state_json) VALUES(?,'ACTIVE','{}')",u);var round=new Round(Long.toString(db.inserted()),0,in.mode(),"ACTIVE",items,items.stream().map(Item::phraseId).toList());db.save(u,round);db.remember(u,req,hash,round);return round;}
 private record Event(Item before,Item after,Phrase phraseBefore,Phrase phraseAfter,String action,boolean correct,String mode,Command command){}
 private void recordEvent(long user,String round,String request,Event event){String action=event.action().equals("PASS")&&!event.correct()?"ERROR":event.action();boolean independent=event.after().passed()&&!event.before().passed()&&event.after().failures()==0&&!event.before().assisted()&&event.mode().equals("WRITE");String rule=event.after().ruleVersion()==null?PhraseSchedule.RULE:event.after().ruleVersion();db.jdbc().update("INSERT INTO vocabulary_phrase_event(user_id,phrase_id,round_id,request_id,action,correct,independent,assisted,failures_before,failures_after,stage_before,stage_after,due_at,rule_version,evidence_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",user,event.after().phraseId(),round,request,action,event.correct(),independent,event.after().failures()>0||event.before().assisted()||event.after().assisted()||event.action().equals("HINT")||event.action().equals("ERROR"),event.before().failures(),event.after().failures(),event.phraseBefore().stage(),event.phraseAfter().stage(),event.phraseAfter().dueAt()==null?null:Timestamp.from(event.phraseAfter().dueAt()),rule,db.encode(event),Timestamp.from(clock.instant()));}
 public Round command(SessionPrincipal a,String id,Command in){long u=user(a,true);if(in==null)throw BusinessException.invalid("action","请选择操作");String req=request(in.requestId()),hash=hash(id,in);var replay=db.replay(u,req,hash);if(replay!=null)return replay;var round=db.round(u,ArticleRules.id(id,"roundId"));if(round==null)throw new BusinessException(404,"PHRASE_NOT_FOUND","词组轮次不存在");if(in.expectedVersion()==null||round.version()!=in.expectedVersion()||round.status().equals("COMPLETED"))throw conflict();String status=round.status(),action=Objects.toString(in.action(),"");var queue=new ArrayList<>(round.queue());var items=new ArrayList<>(round.items());Event event=null;
  if(action.equals("SAVE"))status="PAUSED";else if(action.equals("RESUME"))status="ACTIVE";else {if(!status.equals("ACTIVE")||queue.isEmpty())throw conflict();int index=0;while(!items.get(index).phraseId().equals(queue.getFirst()))index++;var item=items.get(index);Item next=item;var phraseBefore=db.phrase(u,Long.parseLong(item.phraseId()));boolean correct=false;
   switch(action){
    case "DRAFT" -> {String draft=Objects.toString(in.draft(),"");if(draft.length()>160)throw BusinessException.invalid("draft","输入过长");next=new Item(item.phraseId(),item.text(),item.meaningZh(),item.passed(),item.failures(),item.assisted(),item.revealed(),draft,item.answered(),item.ruleVersion());}
    case "REVEAL" -> {if(!round.mode().equals("RECOGNIZE")||item.revealed())throw conflict();next=new Item(item.phraseId(),item.text(),item.meaningZh(),false,item.failures(),item.assisted(),true,item.draft(),false,item.ruleVersion());}
    case "HINT","ERROR" -> {if(item.answered()||item.passed())throw conflict();if(item.revealed()&&!item.assisted())throw conflict();next=PhraseRules.assist(item);}
    case "PASS" -> {if(item.answered()||item.passed())throw conflict();if(round.mode().equals("RECOGNIZE")){if(!item.revealed())throw conflict();correct=Boolean.TRUE.equals(in.known());next=correct?PhraseRules.pass(item):PhraseRules.assist(item);}else {if(in.answer()==null||in.answer().length()>160)throw BusinessException.invalid("answer","请输入完整词组");try{correct=PhraseRules.canonical(in.answer()).equals(PhraseRules.canonical(item.text()));}catch(BusinessException e){correct=false;}next=correct?PhraseRules.pass(item):PhraseRules.assist(item);}next=new Item(next.phraseId(),next.text(),next.meaningZh(),next.passed(),next.failures(),next.assisted(),next.revealed(),next.draft(),true,next.ruleVersion());if(next.passed()&&!item.passed()){var schedule=PhraseSchedule.next(phraseBefore.stage(),next.failures()>0,clock.instant(),item.ruleVersion());db.jdbc().update("UPDATE vocabulary_phrase SET independent_passes=independent_passes+?,stage=?,due_at=?,rule_version=? WHERE user_id=? AND id=?",round.mode().equals("WRITE")&&next.failures()==0&&!item.assisted()?1:0,schedule.stage(),Timestamp.from(schedule.dueAt()),schedule.ruleVersion(),u,item.phraseId());}}
    case "NEXT" -> {if(!item.revealed())throw conflict();queue.removeFirst();if(!item.passed()){queue.add(item.phraseId());next=new Item(item.phraseId(),item.text(),item.meaningZh(),false,item.failures(),false,false,"",false,item.ruleVersion());}if(queue.isEmpty())status="COMPLETED";}
    default -> throw BusinessException.invalid("action","不支持的词组练习操作");
   }items.set(index,next);if(Set.of("HINT","ERROR","PASS").contains(action))event=new Event(item,next,phraseBefore,db.phrase(u,Long.parseLong(item.phraseId())),action,correct,round.mode(),in);
  }var result=new Round(id,round.version()+1,round.mode(),status,items,queue);db.save(u,result);db.remember(u,req,hash,result);if(event!=null)recordEvent(u,round.id(),req,event);return result;
 }
}
